fn v2_response_retreat_stance(self, version, rnd, player, data, debug) -> BattleSubPlanGoal

L14  if version < 2 { return RunAway }                       // v2 미만이면 이 판정 자체를 안 함

L17  team = player[0x930]                                    // 0/1, 2 이상이면 panic
     pos  = Position::as_index(player[0x9c0])                // 0..5 (entity.rs:580 인라인)
     champ = data.cache[0x1e0] /*player_champion[2][5]*/ [team][pos]
     if champ == null { return RunAway }                     // 내 챔피언이 없으면 끝

L20  // 적팀(=1-team) 챔피언 5칸 중 조건을 만족하는 것들 가운데 내 챔피언에서 가장 가까운 하나
L24  nearest = iter_champions(1 - team)                      // player_champion[1-team], None 슬롯 제외
            .filter(CAND)
            .min_by_key(|e| champ.distance_sq(e))            // 동점이면 먼저 나온(슬롯 인덱스가 작은) 쪽 유지

     // CAND(e) = engage.rs:21~23 의 클로저(closure$0). 본체는 담당 범위 밖(m12.ll:41916~41999).
     //   (1) data.blackboard[1-team].is_recent_visible(cache.game, player, e)
     //   (2) && !plan_legacy::old::fight_model::is_ignored_well_enemy(version, player, e)
     //   (3) && champ.distance_sq(e) < 40000000001          // = 200000^2 + 1 -> 거리 <= 200000 (6.25셀)
     //   (1)이 거짓이거나 (2)의 is_ignored 가 참이면 바로 false.
     // IR 상 최초 통과 원소를 찾는 find 루프(5칸 순차 null검사 + CAND 호출)는 이 함수에 인라인돼 있고,
     // 그 뒤 나머지를 도는 min_by_key 의 fold 는 별도 함수(m12.ll:12391~)로 빠져 있다(같은 CAND 사용).

L25  let Some(nearest) = nearest else { return RunAway }      // 후보가 하나도 없으면 도주

L26  near_enemies: Vec<&Entity, &Bump> =
       iter_champions(1 - team).filter(NEAR).collect_in(data.context.pool)
     // NEAR(e) = engage.rs:28~30 의 클로저(closure$2). 본체는 m12.ll:42001~42084.
     //   CAND 와 (1)(2)는 완전히 같고 반경만 다름:
     //   (3) champ.distance_sq(e) < 22500000001             // = 150000^2 + 1 -> 거리 <= 150000 (4.6875셀)
     // 주의: 두 필터 모두 거리 기준점은 champ(내 챔피언)이지 nearest 가 아니다(클로저 캡처가 champ).

L31  die = fight_check::check_kill_die_tick(
           version, rnd, data, player, champ,
           near_enemies,                                     // 위에서 모은 근처 적
L32        Vec::new_in(data.context.pool),                   // 항상 빈 Vec<&Entity>
           debug)

L33  if die > data.context.setting[0x12f8] /*tick_per_second*/ {
L36      return KitingBack { focus: nearest[0x5c0] /*Entity.id*/ }
     }
L38  RunAway

// 요약: '아직 1초(=tick_per_second 틱)보다 오래 버틸 수 있다'고 예측되면 가장 가까운 적을 물고 카이팅,
//       그렇지 않으면 그냥 도주. 조기탈출(버전미달/내챔피언없음/후보없음)은 전부 RunAway.
